    #include <bits/stdc++.h>
using namespace std;

// Function to perform Topological Sort using DFS
void topoSort(int node, vector<int>& vis, stack<int>& st,
              vector<vector<pair<int,int>>>& adj) {

    vis[node] = 1; 

    // Traverse all adjacent nodes
    for (auto &it : adj[node]) {
        if (!vis[it.first]) {
            topoSort(it.first, vis, st, adj);
        }
    }

    // Push node to stack after visiting all neighbors
    st.push(node);
}

// Function to find shortest path in DAG
vector<int> shortestPath(int V, int E, vector<vector<int>>& edges) {

    // Adjacency list: {node -> {adjacent_node, weight}}
    vector<vector<pair<int,int>>> adj(V);

    // Build the graph from given edges
    for (auto &e : edges) {
        int u = e[0];
        int v = e[1];
        int wt = e[2];
        adj[u].push_back({v, wt});
    }

    // Visited array for DFS
    vector<int> vis(V, 0);
    stack<int> st;

    //Perform Topological Sort for all nodes
    for (int i = 0; i < V; i++) {
        if (!vis[i]) {
            topoSort(i, vis, st, adj);
        }
    }

    //Initialize distances
    const int INF = 1e9;
    vector<int> dist(V, INF);
    dist[0] = 0;

    //Process nodes in topological order
    while (!st.empty()) {
        int node = st.top();
        st.pop();

        // If node is reachable
        if (dist[node] != INF) {

            // Relax all adjacent edges
            for (auto &it : adj[node]) {
                int v = it.first;
                int wt = it.second;

                // Update distance if shorter path is found
                if (dist[node] + wt < dist[v]) {
                    dist[v] = dist[node] + wt;
                }
            }
        }
    }

    // Mark unreachable nodes as -1
    for (int i = 0; i < V; i++) {
        if (dist[i] == INF) {
            dist[i] = -1;
        }
    }

    return dist;
}

int main() {

    int V = 6;
    int E = 7;

    // Edge list: {u, v, weight}
    vector<vector<int>> edges = {
        {0,1,2}, {0,4,1}, {4,5,4},
        {4,2,2}, {1,2,3}, {2,3,6}, {5,3,1}
    };

    vector<int> result = shortestPath(V, E, edges);
    for (int x : result) {
        cout << x << " ";
    }

    return 0;
}


