#define MAX_NODES 100

typedef struct Edge {
    int v, wt;
} Edge;

typedef struct Node {
    Edge* edges;
    int size;
} Node;

Node* adj[MAX_NODES];
int vis[MAX_NODES];
int dist[MAX_NODES];

// Function to perform Topological Sort using DFS
void topoSort(int node, int vis[], int st[], int* top, Node* adj[]) {
    vis[node] = 1;

    for (int i = 0; i < adj[node]->size; i++) {
        Edge it = adj[node]->edges[i];
        if (!vis[it.v]) {
            topoSort(it.v, vis, st, top, adj);
        }
    }

    st[(*top)++] = node;
}

// Function to find shortest path in DAG
void shortestPath(int V, int E, int edges[][3]) {
    // Initialize adjacency list
    for (int i = 0; i < V; i++) {
        adj[i] = (Node*)malloc(sizeof(Node));
        adj[i]->edges = (Edge*)malloc(sizeof(Edge) * MAX_NODES);
        adj[i]->size = 0;
    }

    // Build the graph from given edges
    for (int i = 0; i < E; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        int wt = edges[i][2];
        adj[u]->edges[adj[u]->size++] = (Edge){v, wt};
    }

    // Visited array for DFS
    for (int i = 0; i < V; i++) {
        vis[i] = 0;
    }
    int st[V];
    int top = 0;

    // Perform Topological Sort for all nodes
    for (int i = 0; i < V; i++) {
        if (!vis[i]) {
            topoSort(i, vis, st, &top, adj);
        }
    }

    // Initialize distances
    for (int i = 0; i < V; i++) {
        dist[i] = INT_MAX;
    }
    dist[0] = 0;

    // Process nodes in topological order
    for (int i = top - 1; i >= 0; i--) {
        int node = st[i];

        // If node is reachable
        if (dist[node]!= INT_MAX) {
            // Relax all adjacent edges
            for (int j = 0; j < adj[node]->size; j++) {
                Edge it = adj[node]->edges[j];
                int v = it.v;
                int wt = it.wt;
                // Update distance if shorter path is found
                if (dist[node] + wt < dist[v]) {
                    dist[v] = dist[node] + wt;
                }
            }
        }
    }

    // Mark unreachable nodes as -1
    for (int i = 0; i < V; i++) {
        if (dist[i] == INT_MAX) {
            dist[i] = -1;
        }
    }

    // Print the result
    for (int i = 0; i < V; i++) {
        printf("%d ", dist[i]);
    }
}

int main() {
    int V = 6;
    int E = 7;

    // Edge list: {u, v, weight}
    int edges[][3] = {
        {0,1,2}, {0,4,1}, {4,5,4},
        {4,2,2}, {1,2,3}, {2,3,6}, {5,3,1}
    };

    shortestPath(V, E, edges);

    return 0;
}


